-- Phase 9: reconcile all 14 original UN institutional profiles and matching catalogue.
-- Institution verification concerns official mandate/source ONLY, not grant availability.
-- Opportunity status 'unverified' continues to mean NO CURRENT FUNDING CALL CONFIRMED.
-- Idempotent and staff-only: uses existing RLS, no client/anon grants.
alter table public.bov_hub_opportunities add column if not exists institutional_source_verified boolean not null default false;
alter table public.bov_hub_opportunities add column if not exists institutional_source_verified_on date;

insert into public.bov_hub_records(category,title,summary,sectors,source_url,source_reference,verification,verified_at,details)
select 'institution','UNDP — United Nations Development Programme','Official institutional mandate: poverty reduction governance climate resilience livelihoods','{}'::text[],'https://www.undp.org/','Official institutional website — mandate reference','verified',now(),jsonb_build_object('mandate_source_verified',true,'funding_call_verified',false,'scope','Institution identity and mandate only')
where not exists(select 1 from public.bov_hub_records where category='institution' and title='UNDP — United Nations Development Programme');
update public.bov_hub_records set verification='verified',verified_at=coalesce(verified_at,now()),details=details||jsonb_build_object('mandate_source_verified',true,'funding_call_verified',false,'verification_scope','Official institutional identity and mandate; not funding call') where category='institution' and title='UNDP — United Nations Development Programme' and source_url is not null;
insert into public.bov_hub_opportunities(agency,title,country,theme,applicant_types,source_url,status,eligibility,notes,institutional_source_verified,institutional_source_verified_on)
select 'UNDP','Institutional partnership and programme pathways',null,'poverty reduction governance climate resilience livelihoods','{}'::text[],'https://www.undp.org/','unverified','Institutional mandate reference only. No specific funding call, applicant eligibility or open deadline verified.','Official institution source verified. Research actual funding mechanisms and calls separately.',true,current_date
where not exists(select 1 from public.bov_hub_opportunities where agency='UNDP' and title='Institutional partnership and programme pathways');
update public.bov_hub_opportunities set institutional_source_verified=true,institutional_source_verified_on=coalesce(institutional_source_verified_on,current_date) where agency='UNDP' and source_url is not null and source_url like 'https://%';

