-- Audit: should show 14 institutional profiles and 14 agencies represented in matching.
select 'institution_profiles' as metric,count(distinct title)::integer as total from public.bov_hub_records where category='institution'
union all select 'funding_agencies',count(distinct agency)::integer from public.bov_hub_opportunities;
select agency,count(*) as funding_reference_records,bool_or(institutional_source_verified) as official_institution_source_verified from public.bov_hub_opportunities group by agency order by agency;
